def check_good_function(g, a_vals, b_vals):
    # Condition 1: if g(ab) == 0, then g(a) == 0 or g(b) == 0
    for a in a_vals:
        for b in b_vals:
            if a == b: continue
            if g(a*b) == 0:
                if not (g(a) == 0 or g(b) == 0):
                    return False, f"Cond 1 failed for a={a}, b={b}"

    # Condition 2: if g(ab) != 0, then (g(a)-g(b))/(a-b) == g(a)g(b)/g(ab)
    for a in a_vals:
        for b in b_vals:
            if a == b: continue
            if g(a*b) != 0:
                lhs = (g(a) - g(b)) / (a - b)
                rhs = (g(a) * g(b)) / g(a*b)
                if abs(lhs - rhs) > 1e-9:
                    return False, f"Cond 2 failed for a={a}, b={b}: lhs={lhs}, rhs={rhs}"

    # Condition 3: g(1) == 1
    if g(1) != 1:
        return False, "Cond 3 failed"

    return True, "All conditions satisfied"

# Test g(x) = x if x in H else 0
def g_h(x, h_set):
    return x if x in h_set else 0

import itertools

# S_small = a few elements of S
S_small = [2**i * 3**j * 5**k * 7**l for i,j,k,l in itertools.product(range(-1, 2), repeat=4)]

# Test H = {1}
H1 = {1}
res, msg = check_good_function(lambda x: g_h(x, H1), S_small, S_small)
print(f"H={{1}}: {res}, {msg}")

# Test H = {1, -1} (not in S, but good function g should work on R)
# For S, h(x) will just be g(x) for x in S.
# But g(x) must be defined on R.
# Let's test g(x) = x if x in {1, -1} else 0
H2 = {1, -1}
res, msg = check_good_function(lambda x: g_h(x, H2), S_small, S_small)
print(f"H={{1, -1}}: {res}, {msg}")

# Test H = S
# Since we can't have S as a set, we'll use a function for g
def g_s(x):
    # This is a simplified check; we only check it on S_small
    # For the real g, g(x) = x for all x in R.
    return x

res, msg = check_good_function(g_s, S_small, S_small)
print(f"g(x)=x: {res}, {msg}")
